+    test "a value-dropping case is left to the backend's short-circuit" do
+      assert simp("false and x") == {:bin, "and", {:id, "false"}, {:id, "x"}}
+      assert simp("x or true") == {:bin, "or", {:id, "x"}, {:id, "true"}}
+    end
+  end
